\newcommand{\myCylinder}[8]{
\tdplotsetmaincoords{#2}{0}
	\begin{scope}[tdplot_main_coords, scale=#6]
    \coordinate (O) at (0,0,#3);
    \coordinate (O2) at (0,0,0);
    \coordinate (B) at (#1,0,0);
    \coordinate (E) at (#1,0,#3);
    \coordinate (A) at (-#1,0,0);
    \coordinate (F) at (-#1,0,#3);


    \begin{scope}[canvas is xy plane at z=0]
            \draw[color=#4!20,fill=#4!20,fill opacity=#5,opacity=#5] (O2) circle (#1);
            \draw[color=#4!20,fill=#4!10,fill opacity=#5,opacity=#5] (O) circle (#1);
            \draw[very thick, #4,dashed] (B) arc (0:180:#1);
            \draw[very thick, #4,left color=#4!40, right color=#4!70, middle color=#4!30,fill opacity=#5] (B) arc  (0:-180:#1)-- (F) arc  (-180:0:#1) --cycle;

            \draw[very thick, #4] (F) arc (180:0:#1);


	\end{scope}

    %\draw(E) -- (B) (A)--(F);
    \tkzLabelSegment[right](E,B){ #8}
    \tkzLabelSegment[above](E,O){ #7}
    \tkzDrawPoint[color=none, fill=#4](O)
    \tkzDrawSegment[very thick, #4](E,O)

	\end{scope}
}

